CREATE TABLE IF NOT EXISTS personas (
    id_persona INT PRIMARY KEY,
    nombre VARCHAR(50),
    apellido VARCHAR(50),
    edad INT,
    genero CHAR(1),
    ciudad VARCHAR(50),
    estado VARCHAR(50),
    ocupacion VARCHAR(50),
    nivel_estudios VARCHAR(50),
    ingreso_mensual DECIMAL(10,2),
    activo BOOLEAN,
    fecha_registro DATE
);

